/** Reads the stored language preference, defaulting to Indonesian. */
export function getLang() {
    const stored = localStorage.getItem(STORAGE_KEY);
    return stored === "en" ? "en" : DEFAULT_LANG;
}

/** Translates a dictionary key into the current language. */
export function t(key) {
    const lang = getLang();
    return (DICTIONARY[lang] && DICTIONARY[lang][key]) || DICTIONARY[DEFAULT_LANG][key] || key;
}

/** Applies translations to every element with a data-i18n attribute. */
export function applyTranslations() {
    document.querySelectorAll("[data-i18n]").forEach((el) => {
        el.textContent = t(el.getAttribute("data-i18n"));
    });
}

/**
 * Sets the language, re-translates static text, and notifies the rest
 * of the app (sensor.js's dynamic labels) via a custom event — kept as
 * an event instead of a direct import to avoid a circular dependency
 * between i18n.js and sensor.js.
 */
export function setLang(lang) {
    localStorage.setItem(STORAGE_KEY, lang === "en" ? "en" : "id");
    applyTranslations();
    window.dispatchEvent(new CustomEvent("app:languagechange"));
}

/**
 * Wires up the Settings page's language <select id="language-select">.
 * No-ops safely on pages that don't have that element.
 */
export function initLanguageToggle() {
    const select = document.getElementById("language-select");
    if (!select) return;

    select.value = getLang();
    select.addEventListener("change", () => setLang(select.value));
}
